import test from 'node:test';
import assert from 'node:assert/strict';
import {action,summary,settle} from '../src/engine.mjs';
import {receiptDueAt,readDueDays} from '../src/cashflow.mjs';
const now=Date.parse('2026-10-31T12:00Z'),market={prices:{},rate:{annualPct:2.4,fetchedAt:now},events:[]};
const run=(s,a,t=now)=>action(s,market,{requestId:crypto.randomUUID(),...a},t,{parent:true});
const fixture=()=>{let s=run(null,{type:'open_account',name:'Ana'});s=run(s,{type:'setup',config:{start:'2026-10-31',end:'2027-01-31',salary:10,initial:0,expenses:{rent:3,electricity:.5,water:.5},reserve:1,target:0,reward:0,title:'Mi meta'}});return run(s,{type:'receive'})};
test('due dates follow calendar month, end of day, including year rollover',()=>{assert.equal(new Date(receiptDueAt(now,1)).toISOString(),'2026-11-01T23:59:59.999Z');assert.equal(new Date(receiptDueAt(Date.parse('2026-12-31'),5)).toISOString(),'2027-01-05T23:59:59.999Z');assert.equal(new Date(receiptDueAt(Date.parse('2026-11-05T12:00Z'),5)).toISOString(),'2026-11-05T23:59:59.999Z');assert.throws(()=>readDueDays({rent:0},{rent:3}));assert.throws(()=>readDueDays({rent:29},{rent:3}))});
test('changing future dates does not move issued deadlines or duplicate salary',()=>{let s=fixture(),bill=s.bills.find(b=>b.kind==='rent');assert.equal(bill.dueAt,receiptDueAt(now,1));s=run(s,{type:'budget',expenses:{rent:3,electricity:.5,water:.5},reserve:1,dueDays:{rent:8,electricity:5,water:10}});s=settle(s,market,now+1000);assert.equal(s.bills.find(b=>b.id===bill.id).dueAt,bill.dueAt);assert.equal(s.cash,10000);assert.equal(s.bills.length,3)});
test('saving moves only surplus, preserves wealth, is idempotent and can be withdrawn',()=>{let s=fixture();const before=summary(s,market,now);assert.equal(before.available,5000);assert.throws(()=>run(s,{type:'save',amount:6}));const cmd={type:'save',amount:2,requestId:'save-once'};s=run(s,cmd);s=run(s,cmd);assert.equal(s.savings,2000);assert.equal(s.cash,8000);const after=summary(s,market,now);assert.equal(after.netWorth,before.netWorth);assert.equal(after.available,3000);assert.equal(after.profit,0);assert.throws(()=>run(s,{type:'unsave',amount:3}));s=run(s,{type:'unsave',amount:1});assert.equal(s.savings,1000);assert.equal(s.cash,9000);assert.equal(summary(s,market,now).available,4000)});
